CREATE TABLE users (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, email VARCHAR(320) NOT NULL UNIQUE, password_hash VARCHAR(512) NOT NULL, role VARCHAR(16) NOT NULL CHECK (role IN ('ADMIN','USER')), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments (id UUID PRIMARY KEY, client_id VARCHAR(320) NOT NULL REFERENCES users(email), idempotency_key VARCHAR(128) NOT NULL, request_hash VARCHAR(64) NOT NULL, amount NUMERIC(19,4) NOT NULL CHECK (amount > 0), currency VARCHAR(3) NOT NULL, description VARCHAR(240) NOT NULL, status VARCHAR(16) NOT NULL CHECK (status IN ('CREATED','PENDING','PROCESSING','APPROVED','DECLINED','FAILED','REFUNDED')), created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT payments_client_key_uq UNIQUE(client_id,idempotency_key));
CREATE INDEX payments_client_created_idx ON payments(client_id,created_at DESC);
CREATE TABLE payment_attempts (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, payment_id UUID NOT NULL REFERENCES payments(id), attempt_no INTEGER NOT NULL, gateway_key VARCHAR(300) NOT NULL UNIQUE, outcome VARCHAR(32), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT payment_attempts_uq UNIQUE(payment_id,attempt_no));
CREATE TABLE idempotency_records (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, client_id VARCHAR(320) NOT NULL, idempotency_key VARCHAR(128) NOT NULL, request_hash VARCHAR(64) NOT NULL, payment_id UUID REFERENCES payments(id), expires_at TIMESTAMP WITH TIME ZONE NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT idempotency_client_key_uq UNIQUE(client_id,idempotency_key));
CREATE TABLE outbox_events (id UUID PRIMARY KEY, aggregate_id UUID NOT NULL, event_type VARCHAR(100) NOT NULL, payload TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, published_at TIMESTAMP WITH TIME ZONE);
CREATE INDEX outbox_pending_idx ON outbox_events(created_at);
CREATE TABLE processed_messages (message_id UUID PRIMARY KEY, processed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE gateway_charges (gateway_key VARCHAR(300) PRIMARY KEY, payment_id UUID NOT NULL UNIQUE REFERENCES payments(id), result VARCHAR(16) NOT NULL CHECK (result IN ('APPROVED','DECLINED')), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE refunds (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, payment_id UUID NOT NULL UNIQUE REFERENCES payments(id), amount NUMERIC(19,4) NOT NULL CHECK(amount > 0), status VARCHAR(16) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id UUID DEFAULT RANDOM_UUID() PRIMARY KEY, actor VARCHAR(320) NOT NULL, action VARCHAR(100) NOT NULL, entity_id UUID, correlation_id VARCHAR(128), created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);


